import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Epic: Infrastructure","description":"","frontmatter":{},"headers":[],"relativePath":"sovereign-edge/epics/infrastructure.md","filePath":"sovereign-edge/epics/infrastructure.md"}'),r={name:"sovereign-edge/epics/infrastructure.md"};function s(n,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="epic-infrastructure" tabindex="-1">Epic: Infrastructure <a class="header-anchor" href="#epic-infrastructure" aria-label="Permalink to &quot;Epic: Infrastructure&quot;">​</a></h1><blockquote><p>Repo scaffold, RN project setup, CI, and build tooling for iOS/Android.</p></blockquote><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>⏳ In Progress</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Everything needed before feature work can start: the React Native project itself, shared TypeScript/lint/format config, CI, and the native build tooling for both platforms. No product feature lives here.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-0-1-—-repo-scaffold" tabindex="-1">✅ 0.1 — Repo scaffold <a class="header-anchor" href="#✅-0-1-—-repo-scaffold" aria-label="Permalink to &quot;✅ 0.1 — Repo scaffold&quot;">​</a></h4><p><strong>Goal:</strong> Stand up the React Native project this whole app is built on.</p><p><strong>Deliverables:</strong></p><ul><li>React Native project (TypeScript template), targeting iOS + Android.</li><li>Shared TS/ESLint/Prettier config, matching the wider <code>sovereignfs</code> ecosystem&#39;s conventions where they translate (single-quotes, semicolons, Prettier as formatting source of truth).</li><li>Baseline folder structure: chat/inference module, connector framework module, settings/UI module — matching the epic split in this directory so code structure and planning structure stay aligned.</li></ul><p><strong>Dependencies:</strong> none — first task.</p><p><strong>Review checklist:</strong></p><ul><li>✅ Boots a blank app on both platforms&#39; simulators/emulators. Verified by the <code>Native build</code> workflow rather than locally — it builds Release, installs, launches, and asserts the process is still alive ten seconds later on both an iOS simulator and an Android emulator. See the decision in <a href="./../research/0002-react-native-framework-choice.html">research 0002</a>.</li></ul><hr><h4 id="✅-0-2-—-ci-pipeline" tabindex="-1">✅ 0.2 — CI pipeline <a class="header-anchor" href="#✅-0-2-—-ci-pipeline" aria-label="Permalink to &quot;✅ 0.2 — CI pipeline&quot;">​</a></h4><p><strong>Goal:</strong> Lint, typecheck, and test on every PR.</p><p><strong>Deliverables:</strong></p><ul><li>CI workflow running lint, typecheck, and unit tests.</li><li>No model download or real inference in CI — mirrors <code>sovereign</code>&#39;s Core Assistant precedent of a deterministic fake provider so CI never depends on downloading GGUF weights.</li></ul><p><strong>Dependencies:</strong> Task 0.1.</p><p><strong>Review checklist:</strong></p><ul><li>✅ CI fails on a lint/typecheck/test regression; CI does not require downloading any model weights. Two workflows: <code>CI</code> (lint, format, typecheck, test) on every PR, and <code>Native build</code> (build and launch on both platforms) on main and manual dispatch, kept separate so the slow native jobs do not gate every PR. Nothing fetches beyond the package registry, and <code>jest.setup.js</code> makes <code>fetch</code> throw so an accidental network call fails the run.</li></ul><hr><h4 id="📋-0-3-—-native-build-tooling" tabindex="-1">📋 0.3 — Native build tooling <a class="header-anchor" href="#📋-0-3-—-native-build-tooling" aria-label="Permalink to &quot;📋 0.3 — Native build tooling&quot;">​</a></h4><p><strong>Goal:</strong> Reliable, repeatable native builds for both platforms.</p><p><strong>Deliverables:</strong></p><ul><li>Xcode project configuration (signing, capabilities placeholder for future Tier 3 native modules).</li><li>Gradle configuration for Android.</li><li>A build/release script or CI job producing installable builds for internal testing (TestFlight / internal Play track).</li></ul><p><strong>Dependencies:</strong> Task 0.1.</p><p><strong>Review checklist:</strong></p><ul><li>A signed internal build installs and launches on a physical device on both platforms.</li></ul><hr><h4 id="✅-0-4-—-model-asset-pipeline" tabindex="-1">✅ 0.4 — Model asset pipeline <a class="header-anchor" href="#✅-0-4-—-model-asset-pipeline" aria-label="Permalink to &quot;✅ 0.4 — Model asset pipeline&quot;">​</a></h4><p><strong>Goal:</strong> Infrastructure for getting GGUF model weights onto a user&#39;s device without bundling them into the app binary.</p><p><strong>Deliverables:</strong></p><ul><li>Runtime download-and-verify flow for GGUF files (checksum verification, resumable download — addressing the exact failure mode the developer hit trying OGAM).</li><li>On-device storage management (where models live, how they&#39;re listed, how they&#39;re deleted to reclaim space).</li><li>No model weights committed to the repo or bundled into the app binary.</li></ul><p><strong>Dependencies:</strong> Task 0.1.</p><p><strong>Review checklist:</strong></p><ul><li>✅ A model download survives an interrupted connection and resumes or fails cleanly with a clear error, never a silent stuck state. Verified on an Android emulator against a local HTTP origin supporting Range requests, throttling, and a deliberate stall (a socket held open while sending nothing — distinct from a connection error). A stalled transfer failed with <code>code: &#39;stalled&#39;</code> 16s after the last byte and was paused, not cancelled; the retry issued <code>Range: bytes=41943040-</code> and transferred only the remaining 92 MB rather than restarting.</li><li>✅ Verification is chosen from measurement rather than assumption — see <a href="./../research/0003-model-verification-hashing.html">research 0003</a>. Originally size + native MD5 (128 MB in ~500 ms, digest matching the host exactly); superseded by task 0.5, which made publisher-published SHA-256 both stronger and faster.</li></ul><hr><h4 id="✅-0-5-—-native-sha-256-hashing" tabindex="-1">✅ 0.5 — Native SHA-256 hashing <a class="header-anchor" href="#✅-0-5-—-native-sha-256-hashing" aria-label="Permalink to &quot;✅ 0.5 — Native SHA-256 hashing&quot;">​</a></h4><p><strong>Goal:</strong> Verify downloaded models against the digest their publisher actually publishes, at a speed that is usable on a phone.</p><p><strong>Why this exists:</strong> <code>expo-file-system</code> hashes MD5 natively but SHA-256 only in JavaScript, which measured 1.1 MB/s on device — about an hour per 4 GB. Task 0.4 therefore defaulted to MD5. Task 1.2 then showed the cost of that: model publishers publish SHA-256 and never MD5, so an MD5 in the catalog can only come from a maintainer downloading the file and computing it, which certifies &quot;matches what we downloaded&quot; rather than &quot;matches what the publisher published&quot;. Native SHA-256 removes the trade-off instead of managing it.</p><p><strong>Deliverables:</strong></p><ul><li>A local Expo module exposing streaming SHA-256 over a file path, backed by <code>CryptoKit</code> on iOS and <code>MessageDigest</code> on Android.</li><li><code>verifyFile()</code> uses it as the default digest, with the JS implementation retained as a fallback and as a cross-check.</li><li>Catalog entries verified against publisher SHA-256 without opting into a slow path.</li></ul><p><strong>Dependencies:</strong> Task 0.4, Task 1.2.</p><p><strong>Review checklist:</strong></p><ul><li>✅ Hashing on device completes in seconds and the digest is correct. Measured 762–932 MB/s on Android and 599 MB/s on iOS against a 25 MB file — roughly 5–7 s for a 4 GB model, and about 10× faster than <code>expo-file-system</code>&#39;s native MD5, so the stronger digest is now also the cheapest. A known-answer test returns the published SHA-256 of <code>&quot;abc&quot;</code> exactly, and <code>CryptoKit</code>, <code>MessageDigest</code>, and <code>@noble/hashes</code> all agree on the same file. A missing file rejects cleanly rather than crashing.</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../research/0001-concept-and-connector-architecture.html">research 0001</a></li><li><a href="./../research/0003-model-verification-hashing.html">research 0003</a></li></ul>',49)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
